let payload: Payload

const filename = fileURLToPath(import.meta.url)
const dirname = path.dirname(filename)

describe('Scratch group in localized tab', () => {
  beforeAll(async () => {
    ;({ payload } = await initPayloadInt(dirname))
  })

  afterAll(async () => {
    await payload.destroy()
  })

  it('should isolate group field locales inside localized tab', async () => {
    const result = await payload.create({
      collection: tabSlug,
      locale: englishLocale,
      data: {
        tabLocalized: {
          group: { heading: 'heading en' },
        },
      },
    })

    console.log('CREATE RESULT:', JSON.stringify(result.tabLocalized))
    expect(result.tabLocalized?.group?.heading).toBe('heading en')

    await payload.update({
      collection: tabSlug,
      locale: spanishLocale,
      id: result.id,
      data: {
        tabLocalized: {
          group: { heading: 'heading es' },
        },
      },
    })

    const docEn = await payload.findByID({
      collection: tabSlug,
      locale: englishLocale,
      id: result.id,
    })

    const docEs = await payload.findByID({
      collection: tabSlug,
      locale: spanishLocale,
      id: result.id,
    })

    console.log('EN:', JSON.stringify(docEn.tabLocalized), 'ES:', JSON.stringify(docEs.tabLocalized))
    expect(docEn.tabLocalized.group.heading).toBe('heading en')
    expect(docEs.tabLocalized.group.heading).toBe('heading es')
  })
})
